& $ui.Ring $c
if ($Cap) { [void](& $wn.Txt $c (([string]$Cap).ToUpperInvariant()) $ui.F.SmallB $ui.C.Gray 0 ($W - 2 * (& $wn.Sc $PadX)) 'Section' $null) }
