$steps += @{ Name = 'T21 Remove the R27 probe solution'; Title = 'Delete the old test solution'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You delete the solution "90-161.Z probe" that the last round imported (its flows are gone). About 3 minutes.'; Kind = 'guide'; Guide = @('1. On the left, select "Solutions" (it can be under "More").', '2. In the row of "90-161.Z probe", select the three dots (not "probe health" or "probe button").', '3. Select "Delete from this environment".', '4. Select "Delete".', 'If the solution is not in the list: skip it.', 'If it does not delete: select "It failed".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-r27-removed.txt'; Estimate = 180; DoneText = ''; DoneLog = 'Confirmed by you: removed the R27 solution.'; Makes = @(); After = @('T21 Remove the R27 probe flows'); Optional = $false; Help = '' }
