$steps += @{ Name = 'T21 Button flow by hand r4: make a solution'; Title = 'Make a solution for the button flow'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You make an empty solution "90-161.Z probe button" for one flow that you build by hand. About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. If Power Automate asks you to sign in: sign in with your CAC.', '3. On the left, select "Solutions" (it can be under "More").', '4. Select "New solution".', '5. In the box "Display name", type: 90-161.Z probe button', '6. In the box "Publisher", select any publisher in the list.', '7. Select "Create".', '8. Look at the list: the solution "90-161.Z probe button" must be there.', 'If a box or button is missing: select "It failed".'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T21-button-solution.txt'; Estimate = 240; DoneText = ''; DoneLog = 'Confirmed by you: made the button solution.'; Makes = @(); After = @(); Optional = $false; Help = '' }
