$steps += @{ Name = 'T21 Use the list button r4'; Title = 'Use the button in the list'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You select a button in a list view that starts a test flow for that row. About 4 minutes.'; Kind = 'guide'; Guide = @('1. In the browser, select the tab "90-161.Z test page".', '2. Select "Open the list with the button".', '3. Look at the first row for a button "Run the test flow".', '4. In the first row, select "Run the test flow".', '5. Look at the panel that opened for a button "Run".', '6. Select "Run".', '7. If the panel asks you to continue or to allow a connection: select "Continue".', '8. Wait until the panel says the flow ran, or shows an error.', 'If the panel shows an error: select "It failed".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-used.txt'; Estimate = 240; DoneText = ''; DoneLog = 'Confirmed by you: used the button.'; Makes = @(); After = @('T21 Format the form and view r4'); Optional = $false; Help = ''; Answers = @(@{ Key = 'btn-show'; Prompt = 'What did the list show in each row?'; Kind = 'pick'; Choices = @('A button Run the test flow', 'No button', 'The plain list', 'An error') }, @{ Key = 'btn-panel'; Prompt = 'What did the panel say after you selected Run?'; Kind = 'pick'; Choices = @('The flow ran', 'The flow was not found', 'Another error', 'No panel opened') }) }
$steps += @{ Name = 'T22 Read list 1 of 2: cards and keyboard'; Title = 'Read the card and keyboard tests'; Dir = 'T22'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'List 1 of 2. Read it now and do it later, in the window that opens after list 2. All data is FAKE and nothing is sent. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Read these steps now; you do them in the window that opens after the next card.', '2. In the window, select a card in the list on the left.', '3. Select the first button on the card "Your Work".', '4. Select each other card once.', '5. Press Tab to move to the next button, with no mouse.', '6. Press Shift+Tab to move back.', '7. Look for a clear outline on the button that has the focus.', '8. Press Enter to use that button (safe: all data is FAKE and nothing is sent).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T22-list1-read.txt'; Estimate = 60; DoneText = ''; DoneLog = 'Confirmed by you: read the list.'; Makes = @(); After = @(); Optional = $false; Help = '' }
$steps += @{ Name = 'T22 Read list 2 of 2: Narrator and contrast'; Title = 'Read the Narrator and contrast tests'; Dir = 'T22'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'List 2 of 2. Read it now. Then "Done" opens the 90-161.Z window (fake data) full screen: do both lists in it, then close it. About 10 minutes.'; Kind = 'guide'; Guide = @('1. Press Ctrl+Windows+Enter to start Narrator.', '2. Press Tab to move to the next control.', '3. Listen: Narrator should say the name of each control.', '4. Press Ctrl+Windows+Enter again to stop Narrator.', '5. Press Left Alt+Left Shift+Print Screen to turn high contrast on.', '6. If Windows asks to turn on high contrast: select "Yes".', '7. Look at each card: every text and button must stay readable.', '8. Press the same keys again to turn high contrast off.', '9. Close the window with its X.', 'If the window does not open: select "It failed" on the next card.'); Url = ''; UrlConfig = ''; Marker = '90161Z-T22-list2-read.txt'; Estimate = 60; DoneText = ''; DoneLog = 'Confirmed by you: read the list.'; Makes = @(); After = @('T22 Read list 1 of 2: cards and keyboard'); Optional = $false; Help = '' }
$steps += @{ Name = 'T22 Open the 90-161.Z window r2'; Title = 'Open the 90-161.Z window and run the tests'; Dir = 'T22'; File = '90161Z-T22-pfm-window-r2.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Opens your 90-161.Z window with fake data (nothing is read, saved or sent). Do the keyboard, Narrator and contrast tests in it, then close it with its X.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 900; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T22 Read list 2 of 2: Narrator and contrast'); Optional = $false; Help = 'Send the results as they are. The step can be run again.' }
