$steps += @{ Name = 'T22 Answer: keys, Narrator and contrast'; Title = 'Answer 3 questions about keys, Narrator and contrast'; Dir = 'T22'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You answer 3 questions about keyboard, Narrator and high contrast. About 2 minutes.'; Kind = 'guide'; Guide = @('1. Select an answer on each of the next 3 cards.'); Url = ''; UrlConfig = ''; Marker = '90161Z-T22-judged-access.txt'; Estimate = 120; DoneText = ''; DoneLog = 'Confirmed by you: judged keys, Narrator and contrast.'; Makes = @(); After = @('T22 Open the 90-161.Z window r2'); Optional = $false; Help = ''; Answers = @(@{ Key = 'w-keys'; Prompt = 'Could you reach and use every button with the keyboard alone?'; Kind = 'pick'; Choices = @('Yes, every button', 'Most buttons', 'Some buttons', 'No') }, @{ Key = 'w-narrator'; Prompt = 'Did Narrator say the name of each control?'; Kind = 'pick'; Choices = @('Every control', 'Some controls', 'None', 'I could not start Narrator') }, @{ Key = 'w-contrast'; Prompt = 'In high contrast, was every text and button readable?'; Kind = 'pick'; Choices = @('Yes, everything', 'Something was hard to see', 'Something was missing', 'I could not turn it on') }) }
$steps += @{ Name = 'T24 Import the full solution r1: choose the file'; Title = 'Start the import of the full flows'; Dir = 'T24'; File = '90161Z-T24-full-flows-r1.zip'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You start the import of the full 90-161.Z flows (every flow On). The next step finishes it. About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. If Power Automate asks you to sign in: sign in with your CAC.', '3. On the left, select "Solutions" (it can be under "More").', '4. Select "Import solution".', '5. Select "Browse".', '6. Select the box "File name".', '7. In the box "File name", press Ctrl+V (the file path is on the clipboard).', '8. Select "Open".', '9. Select "Next".', 'If the page refuses the file: select "It failed".'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-file-chosen.txt'; Estimate = 240; DoneText = ''; DoneLog = 'Confirmed by you: chose the file.'; Makes = @(); After = @(); Optional = $false; Help = '' }
$steps += @{ Name = 'T24 Import the full solution r1: finish'; Title = 'Finish the import of the full flows'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You finish the import of the full flows. It upgrades the flows you imported in the last round. About 5 minutes.'; Kind = 'guide'; Guide = @('1. If the page says the solution already exists: select "Upgrade".', '2. In each connection box, select the arrow on its right.', '3. Select your connection in the list.', '4. Select "Next".', '5. If the box "1 Site URL" is empty: type the address you typed in the RADE box "Site address".', '6. If the box "2 Alert e-mail" is empty: type your work e-mail address (the one you use in Outlook).', '7. Select "Import".', '8. Wait for the line "Successfully imported".', 'If a box has no connection: select "New connection" in that box.', 'If you selected "New connection": select "Create".', 'If a box has a "Refresh" button: select it.', 'If a sign-in window opens: sign in with your CAC.', 'If the import fails: select "Download log file".', 'If the log file is saved: select "It failed".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T24-imported.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: imported the full solution.'; Makes = @(); After = @('T24 Import the full solution r1: choose the file'); Optional = $false; Help = '' }
$steps += @{ Name = 'T24 Turn on all 6 flows r1'; Title = 'Turn on all 6 flows'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You check that all 6 flows read On and turn on any that do not. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. On the left, select "Solutions" (it can be under "More").', '3. Select the solution "90-161.Z flows".', '4. Find F03 in the column "Status".', '5. Remember if it reads On or Off (the next card asks).', '6. Look at the other 5 flows: each must read On.', '7. If a flow reads Off: select that flow.', '8. If you selected a flow: select "Turn on".', 'If a flow will not turn on: select "It failed".'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-flows-on.txt'; Estimate = 180; DoneText = ''; DoneLog = 'Confirmed by you: all flows On.'; Makes = @(); After = @('T24 Import the full solution r1: finish'); Optional = $false; Help = ''; Answers = @(@{ Key = 'f03-state'; Prompt = 'Before you changed anything, what did F03 read after the import?'; Kind = 'pick'; Choices = @('On', 'Off', 'I did not look') }) }
